-- Part 1 of 4. Run the parts in order.
-- =====================================================================
-- Akeso reference data seed
-- 30 diseases, 74 symptoms, 49 medicines,
-- 97 drug-drug interaction pairs, 12 multi-drug rules.
--
-- Researched from StatPearls (NCBI Bookshelf), WHO, CDC, DOH Philippines,
-- PSMID/PCP, GINA, GOLD, ADA, AHA/ESC, NICE and FDA labels on DailyMed.
-- Every clinical reference URL was opened and checked when this file was
-- made. Textbook ("mother book") references carry no URL on purpose.
--
-- Educational reference content for a student platform, not a substitute
-- for current product labeling or clinical judgment.
--
-- Safe to run more than once: rows with these ids are updated, and their
-- child rows (lists, links, references) are replaced.
-- Requires database/migrations/001_medication_safety_reference.sql.
-- =====================================================================

BEGIN;


-- ---------------------------------------------------------------- body systems
-- Added only when no body system with the same name exists yet.
  SELECT 'bs_cardiovascular', 'Cardiovascular System', 'Heart and blood vessels.', 1
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Cardiovascular System');
  SELECT 'bs_respiratory', 'Respiratory System', 'Airways and lungs.', 2
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Respiratory System');
  SELECT 'bs_digestive', 'Digestive System', 'Gastrointestinal tract, liver and pancreas.', 3
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Digestive System');
  SELECT 'bs_urinary', 'Urinary System', 'Kidneys, ureters, bladder and urethra.', 4
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Urinary System');
  SELECT 'bs_endocrine', 'Endocrine System', 'Hormone-producing glands and metabolism.', 5
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Endocrine System');
  SELECT 'bs_nervous', 'Nervous System', 'Brain, spinal cord and nerves.', 6
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Nervous System');
  SELECT 'bs_immune', 'Immune & Lymphatic System', 'Immune defences and lymphatic tissue.', 7
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Immune & Lymphatic System');
  SELECT 'bs_musculoskeletal', 'Musculoskeletal System', 'Bones, joints and muscles.', 8
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Musculoskeletal System');
  SELECT 'bs_integumentary', 'Integumentary System', 'Skin, hair and nails.', 9
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Integumentary System');
  SELECT 'bs_hematologic', 'Hematologic System', 'Blood and blood-forming tissues.', 10
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Hematologic System');
  SELECT 'bs_multisystem', 'Multisystem (Systemic Infection)', 'Infections that involve several organ systems at once.', 11
  WHERE NOT EXISTS (SELECT 1 FROM public.body_systems WHERE name = 'Multisystem (Systemic Infection)');

-- ---------------------------------------------------------- patient conditions
  SELECT 'hypertension', 'Hypertension', 'High blood pressure', '{hypertension,"blood pressure"}'::text[], 1
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'hypertension');
  SELECT 'diabetes', 'Diabetes Mellitus', 'Type 1 or Type 2', '{diabetes,glycemic,glucose}'::text[], 2
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'diabetes');
  SELECT 'pregnant', 'Pregnancy', 'Gestational / 1st-3rd trimester', '{pregnan}'::text[], 3
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'pregnant');
  SELECT 'asthma', 'Asthma / Reactive Airway', 'Bronchial hyperreactivity', '{asthma,copd,bronch}'::text[], 4
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'asthma');
  SELECT 'peptic_ulcer', 'Peptic Ulcer / GI Bleed', 'Gastric erosion or ulcer history', '{peptic,ulcer,"gi bleed","gastrointestinal bleed"}'::text[], 5
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'peptic_ulcer');
  SELECT 'renal_impairment', 'Chronic Kidney Disease', 'Impaired renal filtration', '{kidney,renal,nephro}'::text[], 6
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'renal_impairment');
  SELECT 'liver_disease', 'Liver Disease', 'Hepatic impairment or cirrhosis', '{liver,hepat,cirrhosis}'::text[], 7
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'liver_disease');
  SELECT 'autoimmune', 'Autoimmune Condition', 'Systemic lupus, RA, or biologics', '{autoimmune,lupus,rheumatoid}'::text[], 8
  WHERE NOT EXISTS (SELECT 1 FROM public.patient_conditions WHERE id = 'autoimmune');

