-- ==================================================================== SYMPTOMS

CREATE TEMP TABLE _seed_symptoms ON COMMIT DROP AS SELECT id, name, scientific_name, description, body_system_id, is_red_flag, diagnostic_weight, weight_rationale, tags, source_attribution, is_published FROM public.symptoms WITH NO DATA;
UPDATE public.symptoms AS x SET name = t.name, scientific_name = t.scientific_name, description = t.description, body_system_id = t.body_system_id, is_red_flag = t.is_red_flag, diagnostic_weight = t.diagnostic_weight, weight_rationale = t.weight_rationale, tags = t.tags, source_attribution = t.source_attribution, is_published = t.is_published, updated_at = now()
  FROM _seed_symptoms AS t WHERE x.id = t.id;
  SELECT id, name, scientific_name, description, body_system_id, is_red_flag, diagnostic_weight, weight_rationale, tags, source_attribution, is_published FROM _seed_symptoms AS t
  WHERE NOT EXISTS (SELECT 1 FROM public.symptoms AS x WHERE x.id = t.id);




COMMIT;
