INSERT INTO _seed_symptoms (id, name, scientific_name, description, body_system_id, is_red_flag, diagnostic_weight, weight_rationale, tags, source_attribution, is_published) VALUES
    ('sym_fever', 'Fever', 'Pyrexia', 'Fever is a regulated elevation of body temperature above the individual''s normal range, produced when pyrogens reset the hypothalamic thermoregulatory set point. It is most often a response to infection but also accompanies inflammatory, malignant, drug-related and other conditions.', NULL, false, 3, 'Fever accompanies a very wide range of infectious and non-infectious illnesses and narrows the differential little on its own.', ARRAY['infection', 'systemic', 'vital-sign']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; Clinical Methods (NCBI Bookshelf)', true),
    ('sym_chills', 'Chills / rigors', 'Rigors (shaking chills)', 'Chills are a sensation of coldness, often with shivering and pallor, that occur as body temperature rises toward a newly elevated set point. Rigors are intense, uncontrollable shaking chills (''teeth-chattering, bed-shaking'') that are associated with rapid temperature rise and suggest bacteremia or other acute infection.', NULL, false, 4, 'Chills accompany most febrile illnesses, although true rigors modestly favour bacteremia, malaria, pyelonephritis and similar infections.', ARRAY['fever', 'infection', 'systemic']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; Clinical Methods (NCBI Bookshelf)', true),
    ('sym_headache', 'Headache', 'Cephalalgia', 'Headache is pain in any region of the head, arising from pain-sensitive intracranial or extracranial structures. Most headaches are primary (migraine, tension-type, cluster), but headache also accompanies systemic infection and can signal serious intracranial disease.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 3, 'Headache is extremely common and accompanies many primary headache disorders and systemic illnesses, so it has low specificity alone.', ARRAY['neurologic', 'pain', 'fever-associated']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_retroorbital_pain', 'Retro-orbital pain (pain behind the eyes)', 'Retro-orbital pain', 'Retro-orbital pain is aching or pressure felt behind the eyeball, often worsened by eye movement. In febrile illness it is a characteristic feature of dengue, accompanying severe headache, myalgia and arthralgia; it also occurs with migraine, sinusitis and orbital disease.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 7, 'In a febrile patient, pain behind the eyes points fairly strongly toward dengue and other arboviral infections.', ARRAY['dengue', 'eye', 'pain', 'fever-associated']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_myalgia', 'Muscle aches (myalgia)', 'Myalgia', 'Myalgia is diffuse or localized pain in skeletal muscles, which may also be felt in the associated tendons, ligaments and fascia. Generalized myalgia is a common feature of systemic viral and bacterial infections, while localized myalgia more often reflects overuse or injury.', (SELECT id FROM public.body_systems WHERE name = 'Musculoskeletal System' ORDER BY id LIMIT 1), false, 4, 'Generalized muscle aches accompany many infections and systemic illnesses and are only weakly discriminating.', ARRAY['musculoskeletal', 'pain', 'viral']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_calf_pain', 'Calf muscle pain / tenderness', 'Calf myalgia', 'Calf pain is pain or tenderness localized to the posterior lower leg muscles. In an acute febrile illness, myalgia characteristically involving the calves and lower back is a recognized feature of leptospirosis; outside that context, calf pain is often musculoskeletal or vascular.', (SELECT id FROM public.body_systems WHERE name = 'Musculoskeletal System' ORDER BY id LIMIT 1), false, 7, 'Febrile illness with prominent calf muscle pain is a classic pointer toward leptospirosis, especially after flood or animal-urine exposure.', ARRAY['leptospirosis', 'musculoskeletal', 'pain']::text[], 'Bates'' Guide to Physical Examination and History Taking; CDC Yellow Book; MedlinePlus Medical Encyclopedia', true),
    ('sym_arthralgia', 'Joint pain (arthralgia)', 'Arthralgia', 'Arthralgia is pain in one or more joints without necessarily visible swelling or inflammation. It may arise from injury, degenerative or inflammatory arthritis, or as part of systemic infection such as dengue (''breakbone fever'').', (SELECT id FROM public.body_systems WHERE name = 'Musculoskeletal System' ORDER BY id LIMIT 1), false, 5, 'Joint pain is common in systemic infection and rheumatic disease; its pattern and accompanying features determine how much it narrows the differential.', ARRAY['musculoskeletal', 'pain', 'arboviral']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_rash', 'Skin rash', 'Exanthem (eruption)', 'A rash is a change in the colour, texture or feel of the skin, which may be macular, papular, vesicular, petechial or urticarial. In febrile illness, a generalized exanthem accompanies many viral infections (e.g., measles, dengue) and some bacterial and drug-related conditions.', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), false, 5, 'Rash is shared by many infections and drug reactions, but its morphology and distribution add useful discriminating information.', ARRAY['skin', 'exanthem', 'fever-associated']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_bleeding', 'Mucosal bleeding / petechiae (gum bleeding, nosebleed)', 'Mucocutaneous hemorrhage (petechiae, epistaxis, gingival bleeding)', 'Mucocutaneous bleeding includes petechiae (pinpoint red dots from capillary bleeding), bruising, nosebleeds (epistaxis) and gum bleeding. In dengue, minor mucocutaneous bleeding may occur, and mucosal bleeding is listed as a warning sign of severe dengue; it also reflects thrombocytopenia or coagulation disorders.', (SELECT id FROM public.body_systems WHERE name = 'Hematologic System' ORDER BY id LIMIT 1), true, 7, 'In an acute febrile illness, spontaneous mucosal bleeding or petechiae strongly suggests dengue or another cause of thrombocytopenia or coagulopathy.', ARRAY['bleeding', 'dengue', 'platelets', 'warning-sign']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_abdominal_pain', 'Abdominal pain', 'Abdominal pain', 'Abdominal pain is pain felt anywhere between the chest and the groin, arising from abdominal organs, the abdominal wall or referred from outside the abdomen. Its location, character, timing and associated features guide the differential, and severity does not always reflect seriousness.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 4, 'Abdominal pain without localisation is common to many gastrointestinal, urinary, gynecological and systemic conditions.', ARRAY['gastrointestinal', 'pain']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_epigastric_pain', 'Epigastric pain', 'Epigastralgia', 'Epigastric pain is pain or burning located in the upper central abdomen below the xiphoid process. It is characteristic of peptic ulcer disease, gastritis and functional dyspepsia, but cardiac, biliary and pancreatic disease may also present here.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 6, 'Pain localised to the epigastrium focuses the differential on upper gastrointestinal causes, while still overlapping with cardiac and pancreaticobiliary disease.', ARRAY['gastrointestinal', 'dyspepsia', 'pain']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_heartburn', 'Heartburn', 'Pyrosis', 'Heartburn is a painful burning feeling just below or behind the breastbone, usually caused by reflux of gastric acid into the esophagus. It is often worse after meals, when lying down or bending over.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 6, 'Retrosternal burning related to meals and posture is fairly characteristic of acid reflux and peptic disease.', ARRAY['gastrointestinal', 'reflux', 'acid']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_nausea_vomiting', 'Nausea & vomiting', 'Nausea and emesis', 'Nausea is an unpleasant sensation of the urge to vomit, and vomiting (emesis) is forceful expulsion of gastric contents through the mouth. Both are common and arise from gastrointestinal, central nervous system, metabolic, drug-related and pregnancy-related causes.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 3, 'Nausea and vomiting occur in a very wide range of gastrointestinal and systemic conditions and are nonspecific alone.', ARRAY['gastrointestinal', 'dehydration']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_diarrhea', 'Diarrhea', 'Diarrhea', 'Diarrhea is the passage of loose or watery stools, typically three or more times a day. Acute diarrhea is most often infectious, while chronic diarrhea suggests malabsorptive, inflammatory or functional disease.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 5, 'Diarrhea points toward intestinal involvement, most often acute infectious gastroenteritis, but also occurs in systemic infections.', ARRAY['gastrointestinal', 'infection', 'dehydration']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_constipation', 'Constipation', 'Constipation (obstipation when severe)', 'Constipation is infrequent bowel movements (commonly fewer than three per week) or hard, dry stools that are difficult or painful to pass. It is most often functional or dietary, but may reflect medicines, metabolic disease or bowel obstruction.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 4, 'Constipation is common and usually functional, adding limited diagnostic information on its own.', ARRAY['gastrointestinal', 'bowel-habit']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Health Topics', true),
    ('sym_melena', 'Black, tarry stools (melena)', 'Melena', 'Melena is the passage of black, sticky, tarry stools with a characteristic foul odour, produced when blood from the upper gastrointestinal tract is digested. It usually indicates bleeding from the esophagus, stomach or duodenum; iron and bismuth can blacken stools but do not make them tarry.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), true, 9, 'Tarry black stool localises bleeding to the upper gastrointestinal tract, most commonly peptic ulcer disease.', ARRAY['gastrointestinal', 'bleeding', 'upper-GI']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_hematemesis', 'Vomiting blood (hematemesis)', 'Hematemesis', 'Hematemesis is vomiting of fresh blood, clots or dark ''coffee-ground'' material from the upper gastrointestinal tract. It indicates bleeding proximal to the ligament of Treitz and requires assessment for hemodynamic instability.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), true, 9, 'Vomiting blood localises bleeding to the upper gastrointestinal tract and is a strong pointer toward peptic ulcer, varices or mucosal tears.', ARRAY['gastrointestinal', 'bleeding', 'upper-GI', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_anorexia', 'Loss of appetite', 'Anorexia', 'Loss of appetite is a reduced desire to eat; the medical term is anorexia (distinct from the eating disorder anorexia nervosa). It accompanies many acute infections as well as chronic, malignant, psychiatric and medicine-related conditions.', NULL, false, 3, 'Reduced appetite is a highly nonspecific accompaniment of many acute and chronic illnesses.', ARRAY['systemic', 'nutrition']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_fatigue', 'Fatigue & malaise', 'Fatigue and malaise', 'Fatigue is a feeling of weariness, tiredness or lack of energy that is not relieved by usual rest, and malaise is a general sense of being unwell. Both accompany a very broad range of infectious, metabolic, hematologic, psychiatric and lifestyle-related conditions.', NULL, false, 3, 'Fatigue and malaise are among the least specific symptoms and occur in most acute and chronic illnesses.', ARRAY['systemic', 'nonspecific']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_weight_loss', 'Unintentional weight loss', 'Unintentional weight loss (cachexia when severe)', 'Unintentional weight loss is a decrease in body weight that occurs without deliberate dieting or exercise. Clinically significant loss (commonly defined as more than 5% of body weight over 6-12 months) warrants evaluation for malignancy, chronic infection, endocrine and gastrointestinal disease.', NULL, false, 5, 'Unintentional weight loss narrows the differential toward chronic infection, malignancy and endocrine disease but remains broad.', ARRAY['systemic', 'chronic', 'nutrition']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_night_sweats', 'Night sweats', 'Nocturnal hyperhidrosis', 'Night sweats are episodes of sweating during sleep severe enough to soak nightclothes or bedding, resulting from exaggeration of the normal circadian temperature rhythm. They may accompany any febrile illness and are classically associated with tuberculosis and lymphoma.', NULL, false, 6, 'Drenching night sweats, especially with weight loss or chronic cough, direct attention toward tuberculosis, lymphoma and other chronic infections.', ARRAY['systemic', 'tuberculosis', 'B-symptom']::text[], 'Bates'' Guide to Physical Examination and History Taking; Clinical Methods (NCBI Bookshelf)', true),
    ('sym_cough', 'Cough', 'Tussis', 'Cough is a protective reflex that expels air forcefully to clear the airways of secretions and irritants. It is classified as acute (under 3 weeks), subacute (3-8 weeks) or chronic (over 8 weeks) and may be dry or productive.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 4, 'Cough is common to most respiratory infections and many airway diseases and discriminates poorly alone.', ARRAY['respiratory', 'airway']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_productive_cough', 'Productive cough (sputum)', 'Productive cough (expectoration)', 'A productive cough brings up sputum from the lower respiratory tract. Purulent sputum (yellow, green, opaque) suggests bacterial infection, rust-coloured sputum is associated with pneumococcal pneumonia, and pink frothy sputum suggests pulmonary edema.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 5, 'Sputum production points to lower respiratory tract involvement, and its character (purulent, rusty, blood-streaked) adds diagnostic value.', ARRAY['respiratory', 'sputum', 'infection']::text[], 'Bates'' Guide to Physical Examination and History Taking; Clinical Methods (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_hemoptysis', 'Coughing up blood (hemoptysis)', 'Hemoptysis', 'Hemoptysis is the expectoration of blood or blood-tinged sputum originating from the lungs or tracheobronchial tree, distinguished from bleeding from the nose, mouth or upper gastrointestinal tract. Massive hemoptysis is a life-threatening emergency.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), true, 8, 'Coughing up blood narrows the differential to a limited set of pulmonary causes, prominently tuberculosis, bronchitis, bronchiectasis, lung cancer and pulmonary embolism.', ARRAY['respiratory', 'bleeding', 'tuberculosis', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; Clinical Methods (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_dyspnea', 'Shortness of breath (dyspnea)', 'Dyspnea', 'Dyspnea is a subjective sensation of uncomfortable or difficult breathing, or of not getting enough air. It arises from respiratory, cardiac, metabolic, hematologic and psychological causes, and severe or sudden dyspnea can indicate a life-threatening condition.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), true, 5, 'Breathlessness points to cardiopulmonary disease but is shared by many respiratory, cardiac and systemic conditions.', ARRAY['respiratory', 'cardiac', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_wheezing', 'Wheezing', 'Wheeze (sibilant rhonchi)', 'Wheezing is a high-pitched, musical sound produced by airflow through narrowed or compressed airways, usually most prominent on expiration. It is characteristic of asthma and chronic obstructive pulmonary disease, but ''all that wheezes is not asthma''.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 7, 'Wheeze indicates airway narrowing and strongly favours obstructive airway diseases such as asthma and COPD.', ARRAY['respiratory', 'airway-obstruction', 'asthma']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; Clinical Methods (NCBI Bookshelf)', true),
    ('sym_chest_tightness', 'Chest tightness', 'Chest tightness', 'Chest tightness is a sensation of constriction or inability to fully expand the chest. It is one of the cardinal symptoms of asthma, often reported more frequently than wheeze, but a sensation of tightness or pressure may also represent myocardial ischemia.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 6, 'Chest tightness with wheeze or cough favours bronchospasm, although overlap with cardiac ischemic pain limits specificity.', ARRAY['respiratory', 'asthma', 'chest']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); Clinical Methods (NCBI Bookshelf)', true),
    ('sym_pleuritic_chest_pain', 'Pleuritic chest pain', 'Pleuritic chest pain (pleurodynia)', 'Pleuritic chest pain is sharp, localized pain in the chest, neck or shoulder that worsens with breathing, coughing or sneezing. It results from irritation or inflammation of the parietal pleura; pulmonary embolism is the most frequent serious cause.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 7, 'Pain that is sharp and worsened by breathing localises the process to the pleura and narrows the differential to pleural, pulmonary and pericardial causes.', ARRAY['respiratory', 'pleura', 'chest-pain']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf)', true),
    ('sym_chest_pain', 'Chest pain or pressure (angina-like)', 'Angina pectoris / anginal chest pain', 'Anginal chest pain is typically a dull, heavy, pressing or crushing substernal discomfort that may radiate to the arm, neck or jaw, is precipitated by exertion or stress and relieved by rest. Chest pain has a broad differential that includes several immediately life-threatening causes.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), true, 7, 'Pressure-like substernal pain with exertional features points toward myocardial ischemia, though other thoracic causes overlap.', ARRAY['cardiac', 'ischemia', 'chest-pain', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_sore_throat', 'Sore throat', 'Pharyngitis (pharyngodynia)', 'Sore throat is discomfort, pain or scratchiness in the throat that often makes swallowing painful. Most cases are due to viral upper respiratory infection; group A streptococcus is the main bacterial cause.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 5, 'Sore throat localises disease to the upper respiratory tract but is shared by many viral and bacterial infections.', ARRAY['respiratory', 'upper-airway', 'infection']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_rhinorrhea', 'Runny nose (coryza)', 'Rhinorrhea (coryza)', 'Rhinorrhea is discharge of fluid from the nose, often with nasal congestion, caused by inflamed nasal mucosa and blood vessels. Coryza (runny nose with sneezing and congestion) is typical of viral upper respiratory infections and is part of the measles prodrome.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 4, 'Runny nose points to the upper respiratory tract but is common to colds, influenza, allergy and measles.', ARRAY['respiratory', 'upper-airway', 'viral']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_conjunctivitis', 'Red eyes (conjunctivitis / conjunctival suffusion)', 'Conjunctival injection / conjunctival suffusion', 'Red eye results from dilated or swollen blood vessels on the surface of the eye. Conjunctivitis involves inflammation with discharge, whereas conjunctival suffusion is redness without purulent discharge that is characteristic of leptospirosis; conjunctivitis is also part of the measles prodrome.', (SELECT id FROM public.body_systems WHERE name = 'Immune & Lymphatic System' ORDER BY id LIMIT 1), false, 6, 'In a febrile patient, conjunctival suffusion or conjunctivitis points toward leptospirosis or measles.', ARRAY['eye', 'leptospirosis', 'measles']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; CDC Yellow Book', true),
    ('sym_koplik_spots', 'Koplik spots', 'Koplik spots (enanthem of measles)', 'Koplik spots are small bluish-white spots, about 2-3 mm, on an erythematous base on the buccal mucosa opposite the molars, likened to ''grains of salt on a red background''. They typically appear about a day before the measles rash and fade as the rash develops.', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), false, 10, 'Koplik spots are considered pathognomonic of measles, so their presence strongly confirms the diagnosis.', ARRAY['measles', 'pathognomonic', 'oral-mucosa']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_anosmia', 'Loss of smell or taste', 'Anosmia / ageusia', 'Anosmia is partial or total loss of the sense of smell, and ageusia or dysgeusia refers to loss or distortion of taste; because flavour depends largely on smell, the two are often reported together. Sudden loss of smell is a recognised feature of viral upper respiratory infections, notably COVID-19.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 7, 'New, sudden loss of smell or taste during an acute respiratory illness is relatively characteristic of COVID-19.', ARRAY['neurologic', 'covid-19', 'special-senses']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_jaundice', 'Jaundice', 'Icterus', 'Jaundice is yellow discolouration of the skin, mucous membranes and sclerae caused by accumulation of bilirubin. Scleral icterus is best appreciated when serum bilirubin exceeds about 3 mg/dL, and causes are grouped as prehepatic, hepatic and posthepatic.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 7, 'Jaundice localises the problem to hemolysis, liver disease or biliary obstruction, and in febrile illness points toward hepatitis, leptospirosis or severe malaria.', ARRAY['hepatobiliary', 'bilirubin', 'leptospirosis']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_dark_urine', 'Dark urine', 'Choluria / abnormal urine colour', 'Dark urine is urine that is dark yellow, tea- or cola-coloured. Dark brown clear urine may reflect bilirubinuria from liver disease, while dark urine can also result from severe dehydration, rhabdomyolysis, hemoglobinuria, blood in the urine or certain foods and medicines.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), false, 6, 'Tea- or cola-coloured urine narrows the differential to liver disease, hemolysis, rhabdomyolysis or hematuria.', ARRAY['urine', 'hepatobiliary', 'hemolysis']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_decreased_urine', 'Decreased urine output (oliguria)', 'Oliguria', 'Oliguria is reduced urine output, commonly defined in adults as less than 400 mL per day (or below about 0.5 mL/kg/h). Causes are classified as prerenal (reduced kidney perfusion, e.g., dehydration or shock), intrinsic renal and postrenal (urinary obstruction).', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), true, 6, 'Reduced urine output points to hypovolemia, shock or acute kidney injury rather than to a specific disease.', ARRAY['renal', 'acute-kidney-injury', 'shock', 'warning-sign']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_dysuria', 'Painful urination (dysuria)', 'Dysuria', 'Dysuria is pain, burning, stinging or itching of the urethra or urethral meatus during urination. Acute cystitis is the most common cause, but urethritis, sexually transmitted infections, vaginitis and prostatitis also cause it.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), false, 7, 'Dysuria localises disease to the lower urinary or genital tract and strongly favours urinary tract infection.', ARRAY['urinary', 'infection', 'UTI']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_urinary_frequency', 'Urinary frequency & urgency', 'Pollakiuria and urinary urgency', 'Urinary frequency is the need to urinate more often than usual, and urgency is a sudden, strong need to urinate. Together they are typical of bladder irritation from infection, but also occur with overactive bladder, prostatic enlargement, pregnancy and diabetes.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), false, 6, 'Frequency with urgency points to the lower urinary tract, most often cystitis, but overlaps with polyuric states.', ARRAY['urinary', 'UTI', 'bladder']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_flank_pain', 'Flank pain', 'Flank pain (loin pain)', 'Flank pain is pain in one side of the body between the upper abdomen and the back. It commonly arises from the kidney or ureter, as in pyelonephritis or kidney stones, and costovertebral angle tenderness may be present.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), false, 7, 'Flank pain localises the process to the kidney or ureter, especially with urinary symptoms or fever.', ARRAY['urinary', 'kidney', 'pyelonephritis']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls (NCBI Bookshelf)', true),
    ('sym_suprapubic_pain', 'Suprapubic pain', 'Suprapubic pain (hypogastric pain)', 'Suprapubic pain is discomfort in the lower midline abdomen above the pubic bone, over the bladder. It is a typical feature of acute cystitis, and suprapubic tenderness may be found on examination.', (SELECT id FROM public.body_systems WHERE name = 'Urinary System' ORDER BY id LIMIT 1), false, 7, 'Suprapubic pain with dysuria and frequency points strongly to lower urinary tract infection.', ARRAY['urinary', 'bladder', 'UTI']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf)', true),
    ('sym_polyuria', 'Excessive urination (polyuria)', 'Polyuria', 'Polyuria is production of abnormally large volumes of urine, generally more than 2.5 L per day in adults, distinct from frequent passage of small volumes. It results from osmotic diuresis (e.g., hyperglycemia), excess fluid intake, diuretics or impaired urine concentration.', (SELECT id FROM public.body_systems WHERE name = 'Endocrine System' ORDER BY id LIMIT 1), false, 6, 'True polyuria, especially with thirst, points to hyperglycemia or other disorders of water balance.', ARRAY['endocrine', 'diabetes', 'urinary']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_polydipsia', 'Excessive thirst (polydipsia)', 'Polydipsia', 'Polydipsia is an abnormal, persistent feeling of needing to drink fluids. It usually accompanies polyuria and dehydration, and is a classic symptom of uncontrolled diabetes mellitus.', (SELECT id FROM public.body_systems WHERE name = 'Endocrine System' ORDER BY id LIMIT 1), false, 6, 'Excessive thirst with polyuria is a classic pointer to hyperglycemia and other water-balance disorders.', ARRAY['endocrine', 'diabetes', 'dehydration']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_blurred_vision', 'Blurred vision', 'Blurred vision', 'Blurred vision is loss of sharpness of vision and inability to see fine details. It may result from refractive errors, lens changes from high blood glucose, cataract, retinal or optic nerve disease, and neurological causes.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 5, 'Blurred vision is shared by ocular, metabolic and neurological disorders and discriminates moderately.', ARRAY['eye', 'diabetes', 'neurologic']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_palpitations', 'Palpitations', 'Palpitations', 'Palpitations are an awareness of the heartbeat as pounding, racing, fluttering or irregular, felt in the chest, throat or neck. They may be benign or reflect arrhythmia, structural heart disease, anemia, thyrotoxicosis or stimulant use.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), false, 5, 'Palpitations point to the heart rhythm but have many benign and systemic causes.', ARRAY['cardiac', 'arrhythmia']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_orthopnea', 'Breathlessness lying flat (orthopnea)', 'Orthopnea', 'Orthopnea is breathlessness in the recumbent position that is relieved by sitting or standing, often quantified by the number of pillows needed to sleep. It is characteristic of left ventricular failure due to redistribution of fluid into the pulmonary circulation, and often occurs with paroxysmal nocturnal dyspnea.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), false, 8, 'Orthopnea is a relatively specific symptom of heart failure with raised pulmonary venous pressure.', ARRAY['cardiac', 'heart-failure', 'respiratory']::text[], 'Bates'' Guide to Physical Examination and History Taking; Clinical Methods (NCBI Bookshelf)', true),
    ('sym_edema', 'Leg swelling (edema)', 'Peripheral edema', 'Peripheral edema is abnormal buildup of fluid in the tissues of the feet, ankles and legs, typically pitting on pressure. Bilateral edema suggests systemic causes such as heart, kidney or liver disease or medicines, while unilateral swelling suggests local venous or lymphatic causes.', (SELECT id FROM public.body_systems WHERE name = 'Cardiovascular System' ORDER BY id LIMIT 1), false, 5, 'Leg edema is shared by cardiac, renal, hepatic, venous and drug-related causes, though distribution helps narrow it.', ARRAY['cardiac', 'fluid', 'heart-failure']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_diaphoresis', 'Sweating (diaphoresis)', 'Diaphoresis', 'Diaphoresis is profuse sweating out of proportion to temperature or activity. It accompanies fever and its defervescence, and cold sweats occur with sympathetic activation in acute coronary syndrome, hypoglycemia, shock and pain.', NULL, false, 4, 'Sweating has many physiological and pathological causes, but diaphoresis with chest pain raises concern for myocardial infarction.', ARRAY['autonomic', 'cardiac', 'fever-associated']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_dizziness', 'Dizziness / lightheadedness', 'Presyncope / vertigo', 'Dizziness is a term used for two main symptoms: lightheadedness (a feeling of faintness) and vertigo (a false sense of spinning or movement). Lightheadedness often reflects reduced blood flow to the brain, while vertigo usually reflects inner ear or brainstem disease.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 3, 'Dizziness is common and arises from cardiovascular, vestibular, metabolic, medication and neurological causes.', ARRAY['neurologic', 'cardiovascular', 'vestibular']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_hemiparesis', 'One-sided weakness or numbness', 'Hemiparesis / hemisensory loss', 'Hemiparesis is weakness of one side of the body, often with numbness (hemisensory loss). Sudden onset is a hallmark of stroke; middle cerebral artery infarction typically causes contralateral weakness and sensory loss affecting the face and arm more than the leg.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 9, 'Sudden one-sided weakness or numbness is a focal neurological deficit that strongly localises to the brain and points toward stroke.', ARRAY['neurologic', 'stroke', 'emergency', 'focal-deficit']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_facial_droop', 'Facial droop', 'Facial paresis', 'Facial droop is weakness of the facial muscles causing asymmetry of the face, such as a drooping mouth corner. Stroke typically causes lower facial weakness with forehead sparing, whereas Bell''s palsy affects the whole side of the face including the forehead.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 9, 'Sudden facial droop is a highly localising neurological sign and a core feature of stroke recognition tools.', ARRAY['neurologic', 'stroke', 'emergency', 'focal-deficit']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_speech_difficulty', 'Slurred or difficult speech', 'Dysarthria / aphasia', 'Speech difficulty includes dysarthria (slurred, poorly articulated speech from weakness or incoordination of speech muscles) and aphasia (impaired production or comprehension of language from injury to the dominant hemisphere). Sudden onset is a classic warning sign of stroke.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 8, 'Sudden slurred speech or language disturbance localises to the brain and strongly suggests stroke or transient ischemic attack.', ARRAY['neurologic', 'stroke', 'emergency', 'focal-deficit']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf); MedlinePlus Medical Encyclopedia', true),
    ('sym_confusion', 'Confusion / altered mental status', 'Delirium / altered mental status', 'Confusion is the inability to think as clearly or quickly as usual, with disorientation and difficulty with attention, memory and decisions. Acute confusion (delirium) is a medical emergency commonly caused by infection, metabolic derangement, hypoxia, drugs or brain disease.', NULL, true, 5, 'Acute confusion signals serious illness but arises from many systemic and neurological causes.', ARRAY['neurologic', 'delirium', 'emergency', 'sepsis']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_photophobia', 'Sensitivity to light (photophobia)', 'Photophobia', 'Photophobia is discomfort or pain in the eyes in response to bright light. It is a common feature of migraine and also occurs with meningitis, subarachnoid hemorrhage and inflammatory eye disease.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 6, 'Photophobia with headache favours migraine but is also a feature of meningeal irritation, giving moderate specificity.', ARRAY['neurologic', 'migraine', 'eye']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_visual_aura', 'Visual aura', 'Visual aura (scintillating scotoma)', 'A visual aura is a transient, fully reversible visual disturbance that develops gradually over at least 5 minutes and lasts up to 60 minutes, often preceding migraine headache. It typically begins as a small area of vision loss or bright shimmering lines (scintillating scotoma) that expands across the visual field.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), false, 8, 'A gradually spreading, positive visual disturbance lasting 5-60 minutes is highly characteristic of migraine with aura.', ARRAY['neurologic', 'migraine']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls (NCBI Bookshelf)', true),
    ('sym_joint_swelling', 'Joint swelling', 'Articular swelling (joint effusion or synovitis)', 'Joint swelling is enlargement of a joint from synovial fluid (effusion), synovial thickening or swelling of the surrounding soft tissues. It distinguishes true arthritis from arthralgia alone and is characterized by the number and pattern of joints involved, acuity and the presence of warmth or redness.', (SELECT id FROM public.body_systems WHERE name = 'Musculoskeletal System' ORDER BY id LIMIT 1), false, 6, 'Objective swelling separates inflammatory arthritis from simple joint pain and, combined with acuity and joint pattern, narrows the differential to arthritides, crystal disease, septic arthritis and viral arthritis such as chikungunya.', ARRAY['musculoskeletal', 'arthritis', 'inflammation', 'chikungunya']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; World Health Organization', true),
    ('sym_ruq_pain', 'Right upper abdominal pain (right upper quadrant)', 'Right upper quadrant abdominal pain', 'Right upper quadrant pain is pain localized beneath the right costal margin, overlying the liver, gallbladder and biliary tree, with contributions from the duodenum, right kidney, hepatic flexure and right lung base. Biliary pain is often steady and may radiate to the right scapula, whereas hepatic pain from capsular stretch is usually a dull ache accompanying hepatitis or congestion.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 6, 'Localization to the right upper quadrant focuses the differential on hepatobiliary disease (cholecystitis, biliary colic, cholangitis, hepatitis), although duodenal, pancreatic, renal and basal pulmonary causes remain possible.', ARRAY['abdominal', 'hepatobiliary', 'liver', 'gallbladder']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls', true),
    ('sym_pale_stool', 'Pale or clay-colored stools', 'Acholic stool', 'Pale, clay-colored (acholic) stools result from reduced delivery of bile pigments to the intestine, so that stercobilin no longer gives stool its normal brown color. The finding indicates cholestasis, either intrahepatic (hepatitis, cirrhosis) or extrahepatic (bile duct obstruction), and usually accompanies jaundice and dark urine.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 8, 'Acholic stool points specifically to impaired bile flow and narrows the differential to hepatitis and biliary obstruction; with jaundice and dark urine it forms a characteristic cholestatic triad.', ARRAY['hepatobiliary', 'cholestasis', 'jaundice', 'liver']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_pruritus', 'Itching (pruritus)', 'Pruritus', 'Pruritus is an unpleasant skin sensation that provokes the desire to scratch. It may be localized, usually from primary skin disease, or generalized, when systemic causes such as cholestatic liver disease, chronic kidney disease, drug reactions or hematologic disorders are considered.', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), false, 3, 'Itching is very common and nonspecific; it narrows the differential mainly when generalized without rash (suggesting systemic causes such as cholestasis) or when paired with a characteristic eruption such as varicella.', ARRAY['skin', 'dermatology', 'cholestasis', 'allergy']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_watery_diarrhea', 'Profuse watery ("rice-water") diarrhea', 'Rice-water stool (secretory diarrhea)', 'Profuse watery diarrhea consists of large-volume, liquid stools; in cholera it is classically pale, flecked with mucus and described as "rice-water". Toxin-mediated intestinal secretion can cause losses of up to about a liter per hour in adults, producing severe dehydration and hypovolemic shock within hours if fluid is not replaced.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), true, 9, 'Painless, high-volume rice-water stools are highly characteristic of cholera and, in the right epidemiologic setting, strongly direct the diagnosis and urgent rehydration.', ARRAY['diarrhea', 'cholera', 'dehydration', 'waterborne', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; World Health Organization; StatPearls', true),
    ('sym_dehydration', 'Signs of dehydration (sunken eyes, dry mouth, intense thirst)', 'Dehydration (volume depletion)', 'Dehydration is a deficit of body water and electrolytes from fluid losses exceeding intake, most often from diarrhea, vomiting, fever, sweating or osmotic diuresis. Clinical signs progress from thirst, dry mucous membranes and reduced dark urine to sunken eyes, reduced skin turgor, tachycardia, confusion and hypovolemic shock.', NULL, true, 5, 'Dehydration reflects severity of fluid loss rather than a specific diagnosis; it narrows attention to diarrheal and vomiting illnesses, uncontrolled hyperglycemia and heat illness, and determines urgency of rehydration.', ARRAY['fluid balance', 'diarrhea', 'cholera', 'systemic']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; World Health Organization', true),
    ('sym_muscle_cramps', 'Muscle cramps', 'Muscle cramps', 'Muscle cramps are sudden, involuntary and painful contractions of a muscle or muscle group, commonly the calves and feet. They occur with overuse and dehydration and with electrolyte disturbances such as hypokalemia, hyponatremia and hypocalcemia, as in the large fluid and electrolyte losses of cholera.', (SELECT id FROM public.body_systems WHERE name = 'Musculoskeletal System' ORDER BY id LIMIT 1), false, 3, 'Cramps are common and mostly benign; they gain significance mainly alongside profuse diarrhea, diuretic use or renal disease, where they suggest electrolyte depletion.', ARRAY['musculoskeletal', 'electrolytes', 'dehydration']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_bite_site_paresthesia', 'Pain or tingling at an animal-bite site', 'Paresthesia at the bite site', 'Pain, itching, tingling or burning at a healed or healing animal-bite or scratch wound can mark the prodrome of rabies as the virus reaches the dorsal root ganglia. It typically appears with nonspecific fever, malaise and headache weeks to months after the exposure and precedes the neurologic phase.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 9, 'New paresthesia at a prior animal-bite site in a febrile patient is a classic early clue to rabies, which is nearly always fatal once clinical signs appear.', ARRAY['rabies', 'animal bite', 'neurologic', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; World Health Organization; StatPearls', true),
    ('sym_hydrophobia', 'Fear of water / throat spasms on swallowing (hydrophobia)', 'Hydrophobia', 'Hydrophobia is a terrifying, involuntary spasm of the pharyngeal, laryngeal and inspiratory muscles provoked by attempts to drink, and in time by the sight, sound or even thought of water. It is the hallmark of furious (encephalitic) rabies and is often accompanied by aerophobia, spasms triggered by a draft of air on the face.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 10, 'Hydrophobia is essentially pathognomonic of rabies encephalitis, especially with a history of animal bite, and signals a disease that is fatal once symptomatic.', ARRAY['rabies', 'encephalitis', 'neurologic', 'emergency', 'pathognomonic']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls; MedlinePlus Medical Encyclopedia', true),
    ('sym_hypersalivation', 'Excessive salivation / drooling', 'Sialorrhea (ptyalism)', 'Hypersalivation and drooling result from excess saliva production or, more often, from an inability to retain or swallow normal saliva. Causes range from oral and pharyngeal infections to neurologic disorders that impair swallowing, and in rabies drooling reflects both autonomic stimulation and painful pharyngeal spasms.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 5, 'Drooling has a broad differential (oral infection, neuromuscular disease, medications); it gains weight when combined with hydrophobia and agitation after an animal bite, as in rabies.', ARRAY['oral', 'neurologic', 'rabies', 'swallowing']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia', true),
    ('sym_agitation', 'Agitation, anxiety or hallucinations', 'Psychomotor agitation', 'Agitation is a state of excessive motor and mental restlessness with irritability or anxiety, which may be accompanied by hallucinations when perception is disturbed. It arises from psychiatric illness but also from delirium due to infection, metabolic disturbance, intoxication or withdrawal, and is a feature of furious rabies.', (SELECT id FROM public.body_systems WHERE name = 'Nervous System' ORDER BY id LIMIT 1), true, 4, 'Agitation is nonspecific, but new agitation or hallucinations with fever suggest delirium or encephalitis (including rabies) and mandate urgent evaluation.', ARRAY['neuropsychiatric', 'delirium', 'encephalitis', 'rabies']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; World Health Organization', true),
    ('sym_abdominal_swelling', 'Abdominal swelling (distension or ascites)', 'Abdominal distension / ascites', 'Abdominal swelling is enlargement of the abdomen from gas, fluid, organ enlargement or masses. Ascites, free fluid in the peritoneal cavity, most often results from portal hypertension and low serum albumin in chronic liver disease, including the periportal fibrosis of chronic Schistosoma japonicum infection, and is suggested by shifting dullness and a fluid wave.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 5, 'Distension alone is nonspecific (gas, obesity, pregnancy); demonstrable ascites narrows the differential to cirrhosis and portal hypertension, heart failure, malignancy and hypoalbuminemic states.', ARRAY['abdominal', 'ascites', 'liver', 'portal hypertension']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_bloody_stool', 'Blood in stool (hematochezia)', 'Hematochezia', 'Hematochezia is the passage of bright red or maroon blood per rectum, alone or mixed with stool. It usually indicates a colonic, rectal or anal source, although brisk upper gastrointestinal bleeding can also present this way; bloody diarrhea with fever suggests invasive infectious or inflammatory colitis.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), true, 7, 'Visible blood localizes the problem to the gastrointestinal tract, most often the lower tract, but the range of causes remains wide from hemorrhoids to colitis, schistosomiasis and colorectal cancer.', ARRAY['gastrointestinal', 'bleeding', 'colitis', 'emergency']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_paroxysmal_cough', 'Coughing fits with a "whoop" (paroxysmal cough)', 'Paroxysmal cough with inspiratory whoop', 'Paroxysmal cough consists of bursts of rapid, uncontrollable coughs on a single expiration, followed by a forced inspiration against a partially closed glottis that produces the characteristic high-pitched whoop. It is the defining feature of the paroxysmal stage of pertussis, although the whoop is often absent in young infants and in adolescents and adults.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 9, 'Paroxysms with an inspiratory whoop are highly characteristic of pertussis and strongly narrow the differential, though absence of the whoop does not exclude it.', ARRAY['respiratory', 'pertussis', 'cough', 'pediatric']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls; MedlinePlus Medical Encyclopedia', true),
    ('sym_posttussive_vomiting', 'Vomiting after coughing fits (post-tussive vomiting)', 'Post-tussive emesis', 'Post-tussive vomiting is vomiting provoked by a severe bout of coughing, caused by the rise in intrathoracic and intra-abdominal pressure and vagal stimulation during paroxysms. It is a characteristic feature of pertussis and should prompt consideration of that diagnosis whenever vomiting follows coughing.', (SELECT id FROM public.body_systems WHERE name = 'Respiratory System' ORDER BY id LIMIT 1), false, 7, 'Vomiting triggered by coughing paroxysms is a recognized clinical criterion for pertussis and considerably raises its likelihood, although forceful coughing from other causes can occasionally do the same.', ARRAY['respiratory', 'pertussis', 'vomiting', 'pediatric']::text[], 'Bates'' Guide to Physical Examination and History Taking; StatPearls; MedlinePlus Medical Encyclopedia', true),
    ('sym_mouth_sores', 'Painful mouth sores or ulcers', 'Oral ulcers (stomatitis)', 'Mouth sores are painful breaks or vesicles in the oral mucosa that often cause difficulty eating, drinking and swallowing. Most are aphthous, traumatic or viral (herpes simplex, enteroviruses in hand, foot and mouth disease), but persistent ulcers may reflect systemic, autoimmune, immunodeficient or malignant disease.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 4, 'Oral ulcers are common and usually benign; they narrow the differential when combined with a pattern such as a hand-foot rash in a child (HFMD) or vesicles elsewhere (varicella).', ARRAY['oral', 'viral', 'ulcers', 'pediatric']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_vesicular_rash', 'Blister-like rash (vesicles)', 'Vesicular eruption', 'A vesicular rash consists of small (under about 1 cm), fluid-filled elevations of the skin. In varicella the vesicles appear in successive crops, starting on the face and trunk, so lesions at all stages from macules to crusts coexist; other patterns include grouped vesicles (herpes simplex), dermatomal vesicles (zoster) and hand-foot-mouth distributions (enterovirus).', (SELECT id FROM public.body_systems WHERE name = 'Integumentary System' ORDER BY id LIMIT 1), false, 7, 'Vesicles narrow the differential to a limited group of viral, contact and bullous conditions, and the pattern (crops at different stages, dermatomal, hand-foot-mouth) often points to a specific diagnosis.', ARRAY['skin', 'rash', 'viral', 'varicella']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_lymphadenopathy', 'Swollen lymph nodes (lymphadenopathy)', 'Lymphadenopathy', 'Lymphadenopathy is enlargement of lymph nodes in size, consistency or number, localized to one region or generalized across two or more non-contiguous regions. Most is reactive to infection, but size, consistency, fixation, location (especially supraclavicular) and duration help separate benign from malignant or systemic causes.', (SELECT id FROM public.body_systems WHERE name = 'Immune & Lymphatic System' ORDER BY id LIMIT 1), false, 5, 'Enlarged nodes are common and mostly reactive; generalized lymphadenopathy or hard, fixed or supraclavicular nodes narrow the differential toward HIV, tuberculosis, lymphoma and metastatic cancer.', ARRAY['lymphatic', 'infection', 'HIV', 'malignancy']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true),
    ('sym_oral_thrush', 'White patches in the mouth (oral thrush)', 'Oropharyngeal (pseudomembranous) candidiasis', 'Oral thrush is Candida overgrowth in the mouth, classically forming creamy white, curd-like plaques on the tongue, buccal mucosa and palate that can be wiped off to leave a red, sometimes bleeding surface. Outside infancy, denture use, antibiotics and inhaled or systemic corticosteroids, it suggests impaired cell-mediated immunity and is an important clinical marker of HIV infection.', (SELECT id FROM public.body_systems WHERE name = 'Digestive System' ORDER BY id LIMIT 1), false, 8, 'Wipeable white plaques are highly characteristic of candidiasis, and unexplained thrush in an adult strongly suggests immunosuppression, notably HIV, or uncontrolled diabetes.', ARRAY['oral', 'fungal', 'HIV', 'immunosuppression']::text[], 'Bates'' Guide to Physical Examination and History Taking; MedlinePlus Medical Encyclopedia; StatPearls', true);
